function maximumSum(nums) {
  const n = nums.length;
  let best = 0;

  for (let core = 1; core <= n; core++) {
    let sum = 0;
    for (let root = 1; core * root * root <= n; root++) {
      sum += nums[core * root * root - 1];
    }
    best = Math.max(best, sum);
  }
  return best;
}

