function maximumSum(nums) {
  // For each position i, add every position j whose product with i is a square.
  // Those positions are pairwise compatible, and any complete set containing i lies among them.
  const n = nums.length;
  const isSquare = (x) => {
    const r = Math.round(Math.sqrt(x));
    return r * r === x;
  };
  let best = 0;
  for (let i = 1; i <= n; i++) {
    let total = 0;
    for (let j = 1; j <= n; j++) {
      if (isSquare(i * j)) total += nums[j - 1];
    }
    if (total > best) best = total;
  }
  return best;
}

